steps.source:
const out = {};
out.caps = q.run(a.capabilities());
try { out.machineHelp = q.help("machine"); } catch(e) { out.machineHelp = String(e); }
out.arms = profiles.arms();
out.functions = run ? "run already bound" : "no run";
JSON.stringify(out).slice(0,4000);

const out = {};
out.capsHelp = q.help("capabilities");
out.machineHelp = q.help("machine");
out.arms = profiles.arms();
JSON.stringify(out).slice(0,5000);

out = {};
out.capsHelp = q.help("capabilities");
out.machineHelp = q.help("machine");
out.arms = profiles.arms();
JSON.stringify(out).slice(0,6000);

const o2 = {};
o2.capsHelp = q.help("capabilities");
o2.machineHelp = q.help("machine");
o2.arms = profiles.arms();
JSON.stringify(o2).slice(0,6000);

var run = a.variant("checked");
var row = run.function("row");
var back = row.timeline("backend");
var ev = run.events("backend");
JSON.stringify({evHelp: q.help("events").slice(0,1200), count: q.run(ev.count())}).slice(0,3000);

var vre = ev.where(e => /virtreg|regalloc|regbank/i.test((e.pass||"")+" "+(e.passName||"")));
var r1 = q.run(vre.select("ordinal","pass","passName","scope","function","header"));
var r2 = q.run(vre.count());
JSON.stringify({count:r2, events:r1}).slice(0,4000);

var np = q.machine.property("NoVRegs");
var res = {};
for (const ord of [71,74,75,78,79]) {
  try { res["after"+ord] = q.run(np.at(back.at(ord).after)); } catch(e){ res["after"+ord] = String(e); }
}
res.names = q.machine.names();
JSON.stringify(res).slice(0,4000);

var seq = q.run(ev.select("ordinal","pass","passName","header"));
var around = seq.rows.filter(r => r.ordinal >= 68 && r.ordinal <= 82);
var props74 = null, props78 = null;
try { props74 = q.run(q.machine.properties().at(back.at(74).after)); } catch(e){ props74 = String(e); }
try { props78 = q.run(q.machine.properties().at(back.at(78).after)); } catch(e){ props78 = String(e); }
JSON.stringify({around, props74, props78}).slice(0,4500);

var np2 = {};
np2.props78 = q.run(q.machine.properties().at(back.at(78).after)).value;
np2.before74 = q.run(np.at(back.at(73).after)).value;   // state after greedy, before first rewriter
np2.at81 = q.run(np.at(back.at(81).after)).value;
np2.at79 = q.run(np.at(back.at(79).after)).value;
np2.propsBefore74 = q.run(q.machine.properties().at(back.at(73).after)).value;
np2.funcCount = q.run(run.functions ? "hasFunctions" : "?");
np2.allNames = q.machine.names();
JSON.stringify(np2).slice(0,2500);

var np3 = {};
np3.props78 = q.run(q.machine.properties().at(back.at(78).after)).value;
np3.NoVRegs_before74_after73 = q.run(np.at(back.at(73).after)).value;
np3.NoVRegs_after79 = q.run(np.at(back.at(79).after)).value;
np3.NoVRegs_after81 = q.run(np.at(back.at(81).after)).value;
np3.propsBefore74 = q.run(q.machine.properties().at(back.at(73).after)).value;
JSON.stringify(np3).slice(0,2000);

var pr = {};
pr.help = q.help("profiles");
pr.armHelp = (function(){ try { return profiles.arm("checked-llvm").help(); } catch(e){ return String(e).slice(0,300);} })();
JSON.stringify(pr).slice(0,3500);

var arm = profiles.arm("checked-llvm").region("row").workload("opening-160-rows");
var tot = {};
for (const m of ["instructions","stackLoads","stackStores"]) {
  try { const r = q.run(arm.total(m)); tot[m] = {value:r.value, unit:r.unit, definition:r.definition, definition2:r.definition||null}; } catch(e){ tot[m] = String(e).slice(0,200); }
}
var d = profiles.arm("checked-llvm").describe();
tot.units = d.units;
tot.treatmentRole = (d.treatment||{}).role;
tot.fieldsStack = (d.fields||null);
JSON.stringify(tot).slice(0,3000);

var fin = {};
fin.rewriterCount = q.run(ev.where(e => e.pass === "virtregrewriter").count()).value;
fin.rewriterOrdinals = q.run(ev.where(e => e.pass === "virtregrewriter").ordinals());
fin.totalBackendEvents = q.run(ev.count()).value;
fin.NoVRegs_last = q.run(np.at(back.at(115).after)).value;
fin.lastHeader = q.run(ev.at(115).select("ordinal","pass")).rows;
JSON.stringify(fin).slice(0,1200);
